<?php elseif($view==='balances'): $rows=query("SELECT w.*,CASE w.owner_type WHEN 'user' THEN (SELECT name FROM users WHERE id=w.owner_id) WHEN 'doctor' THEN (SELECT name FROM doctors WHERE id=w.owner_id) ELSE (SELECT name FROM centers WHERE id=w.owner_id) END owner_name FROM wallets w ORDER BY w.id DESC LIMIT 200")->fetchAll(); ?>
<section class="panel"><h2>کیف پول‌ها</h2><label>جستجو<input type="search" data-live-filter="wallet-rows"></label><div class="table-wrap"><table><thead><tr><th>مالک</th><th>نوع</th><th>موجودی</th></tr></thead><tbody id="wallet-rows"><?php foreach($rows as $w): ?><tr><td><?= esc($w['owner_name']) ?></td><td><?= esc(['user'=>'بیمار/کاربر','doctor'=>'پزشک','center'=>'کلینیک'][$w['owner_type']]) ?></td><td><?= esc(toman($w['balance'])) ?></td></tr><?php endforeach; ?></tbody></table></div><p class="muted">۲۰۰ کیف پول آخر؛ هیچ موجودی ساختگی یا کارمزدی به پزشک تخصیص داده نمی‌شود.</p></section>
<?php else: $rows=query("SELECT p.*,w.owner_type,w.owner_id,CASE w.owner_type WHEN 'user' THEN (SELECT name FROM users WHERE id=w.owner_id) WHEN 'doctor' THEN (SELECT name FROM doctors WHERE id=w.owner_id) ELSE (SELECT name FROM centers WHERE id=w.owner_id) END owner_name FROM wallet_payouts p JOIN wallets w ON w.id=p.wallet_id ORDER BY (p.status='pending') DESC,p.id DESC LIMIT 100")->fetchAll(); ?>
<section class="panel"><h2>درخواست‌های واریز</h2><p>پس از انجام واریز بانکی و بررسی تعلق حساب، مرجع آن را ثبت کنید. این دکمه انتقال بانکی انجام نمی‌دهد.</p></section>
<?php foreach($rows as $p): $bank=json_decode(decrypt_secret($p['bank_snapshot']),true); ?><section class="panel"><h2><?= esc($p['owner_name']) ?> · <?= esc(toman($p['amount'])) ?></h2><p><?= esc(jdate($p['created_at'],true)) ?> · <?= esc(['pending'=>'در انتظار','paid'=>'واریز شد','rejected'=>'رد شد'][$p['status']]) ?></p><dl class="facts"><?php foreach(['holder'=>'صاحب حساب','account'=>'شماره حساب','card'=>'شماره کارت','iban'=>'شبا'] as $key=>$label): ?><dt><?= esc($label) ?></dt><dd><bdi><?= esc($bank[$key]??'') ?></bdi></dd><?php endforeach; ?></dl>
<?php if($p['status']==='pending'): ?><form method="post" data-confirm="رسیدگی مالی این درخواست ثبت شود؟"><?php form_token('wallet_payout_handle'); ?><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><?php input('مرجع بانکی (برای تأیید پرداخت ضروری)','reference','','text',false,120);input('توضیح (برای رد ضروری)','note','','text',false,500); ?><div class="button-row"><button name="status" value="paid"><?= icon('check') ?> واریز انجام شد</button><button name="status" value="rejected" class="danger"><?= icon('close') ?> رد و آزادسازی وجه</button></div></form><?php else: ?><p>مرجع: <?= esc($p['reference']) ?> · <?= esc($p['note']) ?></p><?php endif; ?></section><?php endforeach;if(!$rows): ?><p class="notice">درخواست واریزی ثبت نشده است.</p><?php endif; ?>
